
/**
 * POS Counter information returned by the backend.
 *
 * Each POS Counter belongs to a Branch.
 * Counter Code is generated automatically by the backend.
 */
export interface PosCounter {
  id: number;
  branchId: number;

  /**
   * Automatically generated by the backend.
   * Example: POS001, POS002, POS003.
   *
   * Read-only in the POS Counter Management UI.
   */
  code: string;

  name: string;

  /**
   * Optional identifier of the device assigned
   * to this POS Counter.
   */
  deviceIdentifier: string | null;

  /**
   * Optional default warehouse.
   * Must belong to the same Branch.
   */
  defaultWarehouseId: number | null;

  isActive: boolean;

  /**
   * SQL Server rowversion serialized as Base64 by the API.
   * Required for future updates and status changes.
   */
  rowVersion: string;
}

/**
 * Request body for creating a POS Counter.
 *
 * BranchId comes from the API route.
 * Counter Code is generated automatically by the backend.
 *
 * POST /api/branches/{branchId}/pos-counters
 */
export interface CreatePosCounterRequest {
  name: string;
  deviceIdentifier: string | null;
  defaultWarehouseId: number | null;
}

/**
 * Planned request contract for updating a POS Counter.
 *
 * The Update API has not been implemented yet.
 * Counter Code and BranchId are not editable.
 */
export interface UpdatePosCounterRequest {
  name: string;
  deviceIdentifier: string | null;
  defaultWarehouseId: number | null;

  rowVersion: string;
}

/**
 * Planned request contract for activating or deactivating
 * a POS Counter.
 *
 * The Status Change API has not been implemented yet.
 */
export interface ChangePosCounterStatusRequest {
  rowVersion: string;
}